-- SalonMate targeted marketing MVP extension for Supabase/PostgreSQL.
do $$ begin create type public.platform_role as enum ('CUSTOMER','SALON_OWNER','ADMIN'); exception when duplicate_object then null; end $$;
do $$ begin create type public.booking_status as enum ('Pending','Confirmed','Completed','Cancelled','No-show'); exception when duplicate_object then null; end $$;
do $$ begin create type public.campaign_status as enum ('Draft','Scheduled','Sent','Completed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.marketing_channel as enum ('in_app','whatsapp_click_to_chat','sms_later','email_later'); exception when duplicate_object then null; end $$;
create table if not exists public.customer_visits (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, customer_id uuid references public.customers(id) on delete cascade, booking_id uuid, service_name text, visit_date date not null, amount_inr int default 0, created_at timestamptz default now());
create table if not exists public.customer_segments (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, name text not null, description text, filters jsonb not null default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.campaigns (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, segment_id uuid references public.customer_segments(id), offer_id uuid references public.offers(id), name text not null, channel marketing_channel not null default 'in_app', status campaign_status not null default 'Draft', scheduled_at timestamptz, targeted_count int default 0, sent_count int default 0, view_count int default 0, click_count int default 0, booking_count int default 0, redemption_count int default 0, revenue_inr int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.campaign_recipients (id uuid primary key default gen_random_uuid(), campaign_id uuid references public.campaigns(id) on delete cascade, salon_id uuid references public.salons(id) on delete cascade, customer_id uuid references public.customers(id) on delete cascade, sent_at timestamptz, viewed_at timestamptz, clicked_at timestamptz, booked_at timestamptz, redeemed_at timestamptz, revenue_inr int default 0, created_at timestamptz default now(), unique(campaign_id, customer_id));
create table if not exists public.offer_redemptions (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, offer_id uuid references public.offers(id) on delete cascade, customer_id uuid references public.customers(id) on delete cascade, booking_id uuid, redeemed_at timestamptz default now(), revenue_inr int default 0);
create table if not exists public.favorites (customer_id uuid references public.customers(id) on delete cascade, salon_id uuid references public.salons(id) on delete cascade, created_at timestamptz default now(), primary key(customer_id, salon_id));
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, customer_id uuid references public.customers(id) on delete cascade, rating int check(rating between 1 and 5), body text, created_at timestamptz default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), customer_id uuid references public.customers(id) on delete cascade, salon_id uuid references public.salons(id) on delete cascade, campaign_id uuid references public.campaigns(id) on delete set null, offer_id uuid references public.offers(id) on delete set null, title text not null, body text, read_at timestamptz, created_at timestamptz default now());
create index if not exists customer_visits_salon_customer_idx on public.customer_visits(salon_id, customer_id, visit_date desc);
create index if not exists campaigns_salon_status_idx on public.campaigns(salon_id, status);
create index if not exists campaign_recipients_customer_idx on public.campaign_recipients(customer_id);
create index if not exists offer_redemptions_offer_idx on public.offer_redemptions(offer_id);
alter table public.customer_visits enable row level security; alter table public.customer_segments enable row level security; alter table public.campaigns enable row level security; alter table public.campaign_recipients enable row level security; alter table public.offer_redemptions enable row level security; alter table public.favorites enable row level security; alter table public.reviews enable row level security; alter table public.notifications enable row level security;
create policy customer_visits_salon_scope on public.customer_visits for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy customer_segments_salon_scope on public.customer_segments for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy campaigns_salon_scope on public.campaigns for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy campaign_recipients_salon_scope on public.campaign_recipients for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy offer_redemptions_salon_scope on public.offer_redemptions for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy favorites_customer_or_admin on public.favorites for all using (public.is_super_admin() or exists(select 1 from public.customers c where c.id=customer_id and public.has_salon_access(c.salon_id))) with check (true);
create policy reviews_public_read on public.reviews for select using (true); create policy reviews_customer_insert on public.reviews for insert with check (true);
create policy notifications_customer_read on public.notifications for select using (public.is_super_admin() or public.has_salon_access(salon_id)); create policy notifications_salon_write on public.notifications for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
insert into public.customer_segments(salon_id,name,description,filters) select id, 'Inactive Facial Customers 60+ Days', 'Customers who booked Facial and have not visited in 60+ days', '{"service":"Facial","inactive_days":60}'::jsonb from public.salons on conflict do nothing;
insert into public.customer_segments(salon_id,name,description,filters) select id, 'High-value Customers', 'Customers with total spending above ₹5000', '{"min_spend":5000}'::jsonb from public.salons on conflict do nothing;
